<script setup>
import { computed, ref, watch } from 'vue'
import PrototypeChart from './PrototypeChart.vue'
import BacktestInputs from './BacktestInputs.vue'
import BacktestFilings from './BacktestFilings.vue'
import BacktestBenchmark from './BacktestBenchmark.vue'
import BacktestLifecycles from './BacktestLifecycles.vue'
import BacktestNotices from './BacktestNotices.vue'
import BacktestMarket from './BacktestMarket.vue'
import { dateTime, movement, number } from './model.js'
const developer = new URLSearchParams(location.search).get('developer') === '1'
const props = defineProps({ conditions: Object, report: Object, taskId: String })
const openYear = ref(null)
watch(() => props.report, () => { openYear.value = null })
const defs = [{ key:'total_ret', label:'区间收益', digits:1, unit:'%' }, { key:'cagr', label:'年化收益', digits:2, unit:'%' }, { key:'vol', label:'年化波动', digits:1, unit:'%' }, { key:'sharpe', label:'Sharpe', digits:2, unit:'' }, { key:'max_dd', label:'最大回撤', digits:1, unit:'%' }]
const format = (value, digits, unit = '', signed = false) => value == null || !Number.isFinite(Number(value)) ? '—' : (signed && Number(value) > 0 ? '+' : '') + number(value, digits) + unit
const conditions = computed(() => props.report?.conditions || props.conditions || {})
const nav = computed(() => ({ kind:'nav', title:'净值曲线 vs 沪深300（含成本敏感性）', x:props.report?.nav?.dates || [], series:['strategy','benchmark','strategy_low_cost','strategy_high_cost'].map(key => ({ data: props.report?.nav?.[key] || [] })) }))
const trade = computed(() => props.report?.trades?.find(t => t.year === openYear.value))
const notes = computed(() => props.report?.notes || ['当前为条件预览，尚未启动回测任务；绩效、净值与持仓均未生成。', '执行时须使用历史股票池及当时可得的财报，明确调仓规则、双向成本和成交限制。', '不同成本曲线须来自同策略的独立重算；缺失的基准与持仓不能按零值处理。'])
const blocked = computed(() => props.report?.execution_status === 'BLOCKED')
const checkState = computed(() => ({ RUNNING:'历史采集中', INTERRUPTED:'采集已中断', FAILED:'采集失败 · 回测受阻', CANCELLED:'采集已停止 · 回测受阻', COMPLETED:'数据检查完成 · 回测受阻' })[props.report?.check_status] || '回测受阻')
const checkLabels = { UNAVAILABLE:'缺少输入', PARTIAL:'部分可用', INSUFFICIENT:'覆盖不足' }
const winRate = computed(() => props.report?.win_years != null && props.report?.total_years != null ? props.report.win_years + '/' + props.report.total_years + ' 年跑赢' : '—')
</script>
<template><div class="report-grid backtest-report" :data-report-state="report ? 'result' : 'conditions-preview'">
  <aside class="report-rail"><div class="panel rail-box"><div class="section-title">回测信息</div><div class="kv"><span class="k">区间</span><span class="num" style="font-size:11.5px">{{ report?.meta?.period || '尚未确定' }}</span></div><div class="kv"><span class="k">调仓</span><span style="font-size:11.5px">年度</span></div><div class="kv"><span class="k">单侧成本</span><span class="num">{{ conditions.cost_pct_per_side ?? '—' }}%</span></div><div class="kv"><span class="k">胜率</span><span class="num">{{ winRate }}</span></div><div v-if="developer" class="kv"><span class="k">任务</span><span class="num" style="font-size:10.5px">{{ taskId || report?.meta?.task_id || '未执行' }}</span></div></div><div class="panel rail-box" style="color:var(--text-3);font-size:11.5px;line-height:1.7">股票池：{{ report?.meta?.universe || '尚未绑定历史股票池' }}。历史回测不预示未来收益。</div></aside>
  <main class="report-main"><h1 class="rep-h1">{{ report?.meta?.question || '策略条件与回测报告' }} <span v-if="!report" class="tag tag-warn">条件预览 · 未执行</span><span v-else-if="blocked" class="tag tag-warn">{{ checkState }}</span></h1>
    <section class="panel rep-section"><h2>选股条件</h2><div class="condition-tags"><span v-if="conditions.pe_max != null && conditions.pe_max !== ''" class="tag tag-gold">PE ≤ {{ conditions.pe_max }}</span><span v-if="conditions.roe_min != null && conditions.roe_min !== ''" class="tag tag-gold">ROE ≥ {{ conditions.roe_min }}%</span><span v-if="conditions.rev_yoy_min != null && conditions.rev_yoy_min !== ''" class="tag tag-gold">营收同比 ≥ {{ conditions.rev_yoy_min }}%</span><span class="tag">年度调仓（5月首日）</span><span class="tag">单侧成本 {{ conditions.cost_pct_per_side ?? '—' }}%</span></div><div class="condition-note">{{ report?.execution_status === 'COMPLETED' ? '每年5月首个交易日开盘调仓，按上一交易日收盘已知财报筛选；成交与拒单详见账本。' : report?.conditions?.rebalance || '拟采用每年5月首个交易日调仓；成交规则与历史可得财报待执行时校验。' }}</div></section>
    <section v-if="!developer && report?.data_check" class="panel rep-section"><h2>历史数据可用性</h2><p class="notice">历史输入尚未通过完整准入，未计算收益、净值与持仓。</p><p v-for="check in report.data_check.checks" :key="check.key" class="condition-note"><strong>{{ check.title }}：</strong>{{ check.detail }}</p></section>
    <section v-if="developer && report?.data_check" class="panel rep-section backtest-check" aria-label="回测数据检查"><h2>历史数据准入检查</h2><p class="condition-note">检查截至 {{ dateTime(report.checked_at) }}。目录 {{ report.data_check.instrument_count }} 个证券定义，区间内 {{ report.data_check.checked_snapshot_count }} 份真实冻结快照。以下缺项阻止收益计算。</p><div v-for="check in report.data_check.checks" :key="check.key" class="bt-check-item"><div><strong>{{ check.title }}</strong><span class="tag tag-warn">{{ checkLabels[check.status] || check.status }}</span></div><p>{{ check.detail }}</p></div><details v-if="developer" class="bt-source-details"><summary>查看冻结输入与来源（{{ report.data_check.snapshots.length }}）</summary><div v-for="source in report.data_check.snapshots" :key="source.snapshot_id" class="bt-check-item"><div>{{ source.provider }} / {{ source.dataset }} <span class="tag">{{ source.pit_level }} · 未验证</span></div><p>{{ source.start }} ~ {{ source.end }} · {{ source.row_count }} 行 · {{ source.adjustment }}</p><p class="num">{{ source.snapshot_id }}<br />{{ source.semantic_hash }}</p><p>冻结研究时点 {{ dateTime(source.asof) }} · 抓取 {{ dateTime(source.retrieved_at) }}</p></div><p v-if="!report.data_check.snapshots.length">该区间内没有可检查的冻结快照。</p></details><a class="btn" :href="'/api/quant/backtests/' + encodeURIComponent(report.run_id) + '/export'" download>导出检查报告</a></section>
    <section v-if="developer && report?.historical_data" class="panel rep-section" aria-label="历史数据采集结果"><h2>历史股票池与沪深300基准</h2><p v-if="report.input_audit || report.filing_audit || report.benchmark_audit || report.lifecycle_audit" class="condition-note">沿用上一个冻结版本的历史股票池与基准，来源与哈希保留如下。股票池与基准均为 PARTIAL / 未验证，尚未执行选股。</p><p v-else class="condition-note">{{ {RUNNING:'正在采集',COMPLETED:'采集完成',FAILED:'采集失败',CANCELLED:'采集已停止',INTERRUPTED:'服务中断，请返回原报告重新获取'}[report.check_status] || report.check_status }} · 已请求 {{ report.acquisition?.calls_started ?? 0 }} / {{ report.acquisition?.max_calls ?? 24 }} 次，冻结 {{ report.acquisition?.sources_frozen ?? 0 }} 份响应。股票池与基准均为 PARTIAL / 未验证，尚未执行选股。</p><p v-if="!report.input_audit && !report.filing_audit && !report.benchmark_audit && !report.lifecycle_audit && report.acquisition?.error" class="error-text" role="alert">{{ report.acquisition.error }}</p><div class="table-scroll"><table class="data"><thead><tr><th>年份</th><th>信号日</th><th>执行日</th><th>历史成员</th><th>停牌</th><th>当前已退市</th><th>待核实</th><th>选中数量</th></tr></thead><tbody><tr v-for="a in report.historical_data.annual" :key="a.year"><td>{{ a.year }}</td><td>{{ a.signal_day }}</td><td>{{ a.execution_day }}</td><td>{{ a.member_count ?? '—' }}</td><td>{{ a.suspended_count ?? '—' }}</td><td>{{ a.currently_delisted_count ?? '—' }}</td><td>{{ a.unknown_count ?? '—' }}</td><td>{{ a.eligible_count ?? '未计算' }}</td></tr><tr v-if="!report.historical_data.annual.length"><td colspan="8">交易日历尚未获取，年度信号日未确定。</td></tr></tbody></table></div><p class="condition-note">{{ report.historical_data.benchmark.name }}（价格指数，不含股息再投资）：{{ report.historical_data.benchmark.row_count }} 个交易日，{{ report.historical_data.benchmark.start || '—' }} ~ {{ report.historical_data.benchmark.end || '—' }}。{{ {COVERED:'与已冻结日历覆盖一致',INCOMPLETE:'区间覆盖不足',UNAVAILABLE:'尚未获取'}[report.historical_data.benchmark.coverage] }}，日历内缺少 {{ report.historical_data.benchmark.missing_session_count }} 日；覆盖一致仍需独立来源核对。</p><details class="bt-source-details"><summary>查看历史响应来源与哈希（{{ report.historical_data.sources.length }}）</summary><div v-for="source in report.historical_data.sources" :key="source.sha256" class="bt-check-item"><div>{{ source.provider }} / {{ {calendar:'交易日历',basic:'证券生命周期',members:'历史名单',benchmark:'沪深300价格指数'}[source.query.kind] }} <span class="tag">PARTIAL · 未验证</span></div><p>{{ source.query.day || ((source.query.start || '完整目录') + (source.query.end ? ' ~ ' + source.query.end : '')) }} · {{ source.row_count }} 行 · 抓取 {{ dateTime(source.retrieved_at) }}</p><p class="num">{{ source.sha256 }}</p></div></details><ul class="bt-limitations"><li v-for="note in report.historical_data.limitations" :key="note">{{ note }}</li></ul></section>
    <template v-if="developer"><BacktestInputs :audit="report?.input_audit" :acquisition="report?.acquisition" :status="report?.check_status" :inherited="!!report?.filing_audit || !!report?.benchmark_audit || !!report?.lifecycle_audit || !!report?.notice_audit" />
    <BacktestFilings :audit="report?.filing_audit" :acquisition="report?.acquisition" :status="report?.check_status" :inherited="!!report?.benchmark_audit || !!report?.lifecycle_audit || !!report?.notice_audit" />
    <BacktestBenchmark :audit="report?.benchmark_audit" :acquisition="report?.acquisition" :status="report?.check_status" :inherited="!!report?.lifecycle_audit || !!report?.notice_audit" />
    <BacktestLifecycles :audit="report?.lifecycle_audit" :acquisition="report?.acquisition" :status="report?.check_status" :inherited="!!report?.notice_audit" />
    <BacktestNotices :audit="report?.notice_audit" :acquisition="report?.acquisition" :status="report?.check_status" />
    <BacktestMarket v-if="report?.historical_data" :key="report.run_id" :parent-id="report.run_id" :available="report.check_status === 'COMPLETED'" />
    </template><section v-if="developer && report?.process" class="panel rep-section"><h2>任务记录</h2><div v-for="node in report.process" :key="node.role" class="bt-check-item"><div><strong>{{ node.role }}</strong><span class="tag">{{ {COMPLETED:'职责已完成',NOT_EXECUTED:'未执行',BLOCKED:'受阻',RUNNING:'正在执行',CANCELLED:'已停止',FAILED:'采集失败',INTERRUPTED:'已中断'}[node.status] || node.status }}</span></div><p>{{ node.detail }}</p></div></section>
    <template v-if="developer || report?.execution_status==='COMPLETED'"><section class="panel rep-section"><h2>绩效对比</h2><p v-if="report?.execution_status === 'COMPLETED'" class="condition-note">本报告比较基准为 H00300 沪深300全收益指数；价格指数另存，不混用。</p><p v-if="blocked" class="condition-note">回测数据尚未通过准入，未计算绩效；空缺不是零收益。</p><table class="data"><thead><tr><th>指标</th><th>策略</th><th>沪深300</th><th>超额</th></tr></thead><tbody><tr v-for="d in defs" :key="d.key"><td>{{ d.label }}</td><td :class="['total_ret','cagr'].includes(d.key) ? movement(report?.metrics?.[d.key]) : ''">{{ format(report?.metrics?.[d.key], d.digits, d.unit) }}</td><td :class="['total_ret','cagr'].includes(d.key) ? movement(report?.benchmark_metrics?.[d.key]) : ''">{{ format(report?.benchmark_metrics?.[d.key], d.digits, d.unit) }}</td><td :class="movement(report?.excess_metrics?.[d.key])">{{ ['vol','sharpe'].includes(d.key) ? '—' : format(report?.excess_metrics?.[d.key], d.digits, d.unit, true) }}</td></tr></tbody></table></section>
    <section class="panel rep-section"><h2>{{ nav.title }}</h2><PrototypeChart :block="nav" :height="340" :empty="report?.nav?.dates?.length ? '' : blocked ? '数据未通过准入，未生成净值与成本敏感性曲线' : '回测尚未执行，暂无净值与成本敏感性数据'" /></section>
    <section class="panel rep-section"><h2>分年度表现</h2><table class="data"><thead><tr><th>年份</th><th>策略</th><th>沪深300</th><th>超额</th><th>持股数</th></tr></thead><tbody><tr v-for="a in report?.annual || []" :key="a.year" class="annual-result" tabindex="0" @click="openYear = openYear === a.year ? null : a.year" @keydown.enter.prevent="openYear = openYear === a.year ? null : a.year"><td>{{ a.year }} {{ openYear === a.year ? '▾' : '▸' }}</td><td :class="movement(a.strategy)">{{ format(a.strategy,1,'%',true) }}</td><td :class="movement(a.benchmark)">{{ format(a.benchmark,1,'%',true) }}</td><td :class="movement(a.excess)">{{ format(a.excess,1,'%',true) }}</td><td>{{ a.n_stocks ?? '—' }}</td></tr><tr v-if="!report?.annual?.length"><td colspan="5" class="result-unavailable">尚无年度收益与持仓记录</td></tr></tbody></table><div v-if="openYear != null" class="annual-holdings"><template v-if="trade"><div>{{ openYear }} 年选中名单（{{ trade.signal_day || trade.report_date }} 已知财报；选中不代表全部成交，实际持仓见日终账本）</div><table class="data"><thead><tr><th>代码</th><th>名称</th><th>PE</th><th>ROE%</th><th>营收同比%</th><th>执行日参考开盘价</th></tr></thead><tbody><tr v-for="s in trade.stocks || []" :key="s.code"><td class="num">{{ s.code }}</td><td>{{ s.name }}</td><td>{{ number(s.pe,1) }}</td><td>{{ number(s.roe,1) }}</td><td>{{ number(s.rev_yoy,1) }}</td><td>{{ number(s.buy_price,2) }}</td></tr></tbody></table></template><div v-else>该年度持仓明细不可用。</div></div></section>
    </template><section class="panel rep-section"><h2>方法说明与过拟合提示</h2><ul style="margin:0;padding-left:18px;color:var(--text-2);font-size:12.5px;line-height:1.8"><li v-for="note in notes" :key="note">{{ note }}</li></ul></section><div class="disclaimer">{{ report?.disclaimer || '本工具为投研参考，不构成投资建议。历史回测不代表未来收益。' }}</div>
  </main>
</div></template>
